import ozl.startup.Session;import java.nio.file.*;import java.util.*;import java.nio.charset.StandardCharsets;
public final class OwnedStartupSessionTest {
 static String enc(Path p){return Base64.getEncoder().encodeToString(p.toString().getBytes(StandardCharsets.UTF_8));}
 static void check(boolean x,String why){if(!x)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{Path root=Path.of(args[0]).toRealPath(),game=Files.createDirectories(root.resolve("game")),user=Files.createDirectories(root.resolve("user")),context=Files.createDirectories(root.resolve("独立 配置")),folder=Files.createDirectories(context.resolve("runtime/live-123456abcdef/startup")),agent=folder.resolve("OrangeStartup.jar");Files.writeString(agent,"fixture");long now=System.currentTimeMillis()/1000;String receipt="version=OZLOWN1\nsession=1234567890abcdef1234567890abcdef\ncreated="+now+"\nexpires="+(now+600)+"\ngame="+enc(game)+"\nuser="+enc(user)+"\ncontext="+enc(context)+"\nissues="+enc(folder.resolve("issues.txt"))+"\ntheme=dark\nreducedMotion=false\n";Files.writeString(folder.resolve("session.properties"),receipt);System.setProperty("ozl.startup.context",context.toString());check(Session.read(agent,game,now)!=null,"owned startup receipt accepted outside real game");System.setProperty("ozl.startup.context",root.toString());check(Session.read(agent,game,now)==null,"wrong context rejected");System.clearProperty("ozl.startup.context");check(Session.read(agent,game,now)==null,"owned receipt requires explicit transport context");Path legacy=Files.createDirectories(game.resolve("OrangeLauncherRuntime/startup"));Files.writeString(legacy.resolve("OrangeStartup.jar"),"fixture");Files.writeString(legacy.resolve("session.properties"),receipt.replace("OZLOWN1","OZL1").replace("context="+enc(context)+"\n","").replace(enc(folder.resolve("issues.txt")),enc(legacy.resolve("issues.txt"))));check(Session.read(legacy.resolve("OrangeStartup.jar"),game,now)!=null,"legacy frozen receipt unchanged");System.out.println("PASS 4 owned startup JVM receipt assertions");}
}
